    rv = CreateFolderAndCache(this, actualName, getter_AddRefs(folder));
    if (NS_FAILED(rv) && rv != NS_MSG_FOLDER_EXISTS) {
      return rv;
    }

    // `CreateFolderAndCache` will return `NS_MSG_FOLDER_EXISTS` in two cases:
    // 1. This folder object already has a child with the specified name.
    // 2. This folder object already has a child with the specified URI.
    // In both cases, that means `mSubFolders` already contains a child with the
    // given name. This cannot be treated as an error condition because the
    // folder lookup service enforces pointer identity for live (parented)
    // folders, so a folder cached with this folder's URI that is still in the
    // tree will also already be in our children list.
    // This branch can be further simplified once all dangling folder paths are
    // removed. See bug 1679333.
    if (NS_SUCCEEDED(rv)) {
      mSubFolders.AppendObject(folder);
    }
#ifdef MOZ_PANORAMA
  }
#endif  // MOZ_PANORAMA
  MOZ_ASSERT(folder, "there must be a folder");

  folder->SetFlag(flags | nsMsgFolderFlags::Mail);
  folder.forget(child);
  return NS_OK;
